const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],escape=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sound=new SalonSound();let session=null,active=2,selected=null,sticker=null,view='both',action=null,lastFrame=performance.now(),dirtyFrame=false,saveTimer,toastTimer,paused=false,rotate=false,past=[],future=[],bootError='',saveBlocked=false,rewardCleanup=()=>{};
try{session=loadSession();}catch{bootError='服务记录读取失败，原始记录已保留。可从备份恢复，或开始新的服务。';saveBlocked=true;}
$('#app').innerHTML=`<header class="salon-header"><button class="wordmark" id="home" aria-label="返回预约本">${icon('flower')}<span>指间诗<small>THE LITTLE NAIL ATELIER</small></span></button><section class="music-dock" aria-label="工作室音乐播放器"><span class="music-dock-badge" aria-hidden="true">${icon('music')}</span><div class="music-dock-song"><label for="dock-track">工作室音乐 <span id="dock-status" role="status"></span></label><select id="dock-track" aria-label="选择工作室伴奏">${MUSIC_TRACKS.map((t,i)=>`<option value="${i}">${t.title}</option>`).join('')}</select></div><div class="music-dock-buttons"><button id="dock-prev" aria-label="上一首伴奏" title="上一首">${icon('previous')}<small>上一首</small></button><button id="dock-toggle" aria-label="播放伴奏" title="播放">${icon('play')}<small>播放</small></button><button id="dock-next" aria-label="下一首伴奏" title="下一首">${icon('next')}<small>下一首</small></button></div><label class="music-dock-volume" for="dock-volume">${icon('sound')}<output id="dock-volume-value">${Math.round(sound.channels.music*100)}%</output><input id="dock-volume" type="range" aria-label="工作室伴奏音量" min="0" max="1" step=".01" value="${sound.channels.music}"></label></section><nav><button id="wallet" class="wallet-badge" aria-label="查看游戏金币收入"><span aria-hidden="true">✦</span><output>0</output><small>金币</small></button><a href="?mode=free" title="保留原有自由绘画与作品收藏">${icon('paint')}<span>自由创作</span></a><button id="album">${icon('shelf')}<span>作品集</span></button><button id="settings" aria-label="声音与设置">${icon('sound')}<span>声音设置</span></button><button id="help" aria-label="操作说明">${icon('help')}</button></nav></header>
<main class="salon-main"><section class="salon-stage"><div id="salon-world" aria-label="三维美甲工作台"></div><div id="scene-title" class="scene-caption"></div><div id="scene-controls" class="scene-controls"><button data-view="detail">单指</button><button data-view="hand">单手</button><button data-view="both" class="active">双手</button><button id="side-view" title="查看侧面厚薄">侧面</button><button id="rotate" title="切换编辑或旋转">${icon('view')}</button></div><div id="stage-tools" class="stage-tools"></div><div id="contact-feedback" class="contact-feedback" aria-hidden="true"></div><div id="plan-board" class="plan-board" hidden></div><div id="welcome" class="welcome-layer"></div><div class="stage-bottom"><button id="undo" aria-label="撤销本阶段操作">${icon('undo')}</button><button id="redo" aria-label="重做">${icon('redo')}</button><span id="stage-hint"></span><span class="signature">a little colour, a little you.</span></div><nav id="finger-strip" class="finger-strip" aria-label="十指施工进度"></nav><div id="lamp-overlay" class="lamp-overlay" hidden></div></section><aside id="salon-panel" class="salon-panel"></aside></main><dialog id="salon-dialog"></dialog><div id="salon-toast" class="salon-toast" role="status" hidden></div><input id="backup-input" type="file" accept=".json,application/json" hidden>`;
const scene=new NailScene($('#salon-world'),()=>{}),objects=addSalonObjects(scene);
scene.sync(targetDesign(CLIENTS[0]));scene.focus('both');
$('#salon-world').addEventListener('render-lost',()=>{stop();persist();toast('画布连接中断，服务记录已保留。',6000);});
function toast(message,time=3200){$('#salon-toast').textContent=message;$('#salon-toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#salon-toast').hidden=true,time);}
function persist(){if(!session||saveBlocked)return;try{saveSession(session);$('#save-label')?.replaceChildren(document.createTextNode('已保存 · 当前浏览器'));}catch{toast('保存失败，请打开设置导出服务备份。',6000);}}
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(persist,350);}
function remember(){past.push(clone(session));if(past.length>25)past.shift();future=[];}
function restore(redo=false){if(session?.lamp)return;stop();const from=redo?future:past,to=redo?past:future;if(!from.length)return;to.push(clone(session));session=from.pop();selected=null;refresh();scheduleSave();}
function stop(){action=null;sound.stopContact();objects.tool(null);$('#contact-feedback').className='contact-feedback';}
function mutate(fn){remember();clearTimeout(toastTimer);$('#salon-toast').hidden=true;fn();refresh();scheduleSave();}
function nailSVG(n,id='n',w=56,h=100){const shape=Array.from({length:51},(_,i)=>{const v=i/50;return `${(.5-halfWidth(n.shape,v))*80},${(1-v)*120}`;}).concat(Array.from({length:51},(_,i)=>{const v=1-i/50;return `${(.5+halfWidth(n.shape,v))*80},${(1-v)*120}`;})).join(' ');return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="-5 -5 90 130"><defs><linearGradient id="${id}"><stop stop-color="${n.base}"/><stop offset=".4" stop-color="${n.gradient?.color||n.base}"/><stop offset="1" stop-color="${n.base}"/></linearGradient><clipPath id="c${id}"><polygon points="${shape}"/></clipPath></defs><polygon points="${shape}" fill="url(#${id})"/><g clip-path="url(#c${id})">${n.finish==='catEye'?'<path d="M-5 90 90 12" stroke="#f1dca0" stroke-width="12" opacity=".7"/><path d="M-5 90 90 12" stroke="#fff3ce" stroke-width="3" opacity=".65"/>':''}${n.pattern==='french'?'<path d="M0 0H80V14Q40 5 0 14Z" fill="#fff6e6"/>':''}${n.pattern==='marble'?'<path d="M-5 25Q70 65 20 95T90 120M0 5Q70 30 80 80" fill="none" stroke="#fff3e0" stroke-width="3" opacity=".65"/>':''}<path d="M18 25Q9 60 17 96" stroke="#fff" stroke-width="4" opacity=".25" fill="none"/>${n.decorations.filter(d=>!d.hidden).map(d=>`<text x="${d.u*80}" y="${(1-d.v)*120+7}" text-anchor="middle" font-size="${22*d.scale}" fill="${d.type==='flower'?'#fff4d8':d.type==='foil'||d.type==='star'?'#dbc07d':'#f6e8db'}" transform="rotate(${d.rotation*180/Math.PI} ${d.u*80} ${(1-d.v)*120})">${({flower:'✿',star:'✦',heart:'♥',pearl:'●',gem:'◆',bow:'୨୧',butterfly:'ʚɞ',foil:'✧'})[d.type]}</text>`).join('')}</g></svg>`;}
function reference(c){const d=targetDesign(c);return `<div class="reference-card" style="--client:${c.color}"><div class="ref-top"><span>INSPIRATION / ${String(CLIENTS.indexOf(c)+1).padStart(2,'0')}</span><span>✧</span></div><div class="reference-nails">${d.nails.slice(0,5).map((n,i)=>nailSVG(n,c.id+i,38,76)).join('')}</div><div class="reference-nails right-ref">${d.nails.slice(5).map((n,i)=>nailSVG(n,c.id+'r'+i,29,56)).join('')}</div><div class="ref-bottom"><strong>${c.title}</strong><em>the little nail atelier</em></div></div>`;}
function portrait(c){return `<svg viewBox="0 0 120 140" class="portrait" aria-hidden="true"><defs><linearGradient id="p${c.id}" x2="1" y2="1"><stop stop-color="${c.color}"/><stop offset="1" stop-color="#efe0cd"/></linearGradient></defs><rect width="120" height="140" rx="60" fill="url(#p${c.id})"/><circle cx="60" cy="54" r="30" fill="#574339"/><path d="M22 140Q19 92 60 93Q101 92 104 140" fill="${c.palette[0]}"/><path d="M49 81H71V104Q60 113 49 104" fill="${c.skin}"/><ellipse cx="60" cy="59" rx="23" ry="30" fill="${c.skin}"/><path d="M34 57Q22 18 60 22Q100 21 86 61L78 40Q51 60 34 57" fill="#554137"/><path d="M47 64h5m16 0h5M55 79q5 3 10 0" stroke="#815a4c" stroke-width="2" fill="none" stroke-linecap="round"/><circle cx="37" cy="74" r="3" fill="#e7ce99"/><circle cx="83" cy="74" r="3" fill="#e7ce99"/></svg>`;}
function welcome(){stop();$('#welcome').hidden=false;$('#plan-board').hidden=true;$('#salon-panel').hidden=true;$('#finger-strip').hidden=true;$('#scene-controls').hidden=true;$('#stage-tools').innerHTML='';$('#scene-title').innerHTML='';$('#stage-hint').textContent='';scene.sync(targetDesign(CLIENTS[0]));scene.focus('both');scene.controls.enabled=false;
 $('#welcome').innerHTML=`<div class="welcome-copy"><div class="eyebrow">SLOW DAYS, BEAUTIFUL DETAILS</div><h1>把一点心意，<br>留在指尖。</h1><p>看懂每一份期待，照顾每一种甲况。<br>从十指设计，到亲手完成的一束光。<br>今天，你的小小工作室开门了。</p><button class="salon-primary" id="open-book">翻开今日预约 ${icon('arrow')}</button>${session?'<button class="resume-button" id="resume">继续上次的服务 →</button>':''}<div class="welcome-tags">顾客定制 <span>·</span> 十指设计 <span>·</span> 沉浸手作</div></div><div class="welcome-note"><span>OPEN</span><p>有花，有光，<br>也有慢慢完成的美。</p><small>EST. 2026 · 指间诗</small></div><div class="welcome-bottom">手作的温度，藏在每一个细节里。</div>`;
 $('#open-book').onclick=async()=>{unlock();book();};if($('#resume'))$('#resume').onclick=async()=>{unlock();refresh();if(session.consultation&&session.consultation.length<4)consultation();};if(bootError)toast(bootError,6500);
}
async function unlock(){const ok=await sound.init();updateMusicUi();if(!ok)toast('部分声音未能载入，操作不受影响，可稍后在设置重试。');}
function modal(title,body,kind=''){stop();sound.lamp(false);scene.controls.enabled=false;const d=$('#salon-dialog');if(d.open)d.close();d.className=kind;d.innerHTML=`<div class="modal-head"><div><small>THE LITTLE NAIL ATELIER</small><h2>${title}</h2></div><button class="close-modal" aria-label="关闭">${icon('close')}</button></div>${body}`;d.showModal();d.querySelector('.close-modal').onclick=()=>d.close();}
$('#salon-dialog').addEventListener('close',()=>{scene.controls.enabled=!$('#salon-dialog').open&&$('#welcome').hidden;paused=false;});
function book(){rewardCleanup();persist();modal('今天，为谁留一点美？',`<p class="modal-intro">每位顾客都带着自己的参考图。先看看她的甲况与心愿。</p><div class="client-grid">${CLIENTS.map(c=>`<button class="client-card" data-client="${c.id}" style="--client:${c.color}"><div class="client-top">${portrait(c)}<div><small>${c.role}</small><h3>${c.name}</h3><span>${c.route==='repair'?'局部维修':c.old?'卸旧重做':c.route==='tips'?'全贴甲片':'本甲建构'}</span></div></div>${reference(c)}<p>“${c.quote}”</p><div class="client-bottom"><span>查看预约 →</span><small>${c.price} 金币</small></div></button>`).join('')}</div>`,'book-dialog');
 $$('[data-client]').forEach(b=>b.onclick=()=>{const c=customer(b.dataset.client);sound.one('pick');modal(`${c.name}的预约`,`${reference(c)}<blockquote>“${c.quote}”</blockquote><div class="appointment-detail"><p><b>本次需求</b>${c.limit}</p><p><b>初始甲况</b>${c.old==='tips'?'旧甲片、局部翘起':c.old==='gel'?'旧色胶、磨损不一':'自然本甲、各指长度不同'}${c.dirty?'；部分指尖有污垢，需清洁':''}</p><p><b>参考与预算</b>以此图的甲形、色系和重点图案为准 · ${c.price} 金币</p></div>${session?'<p class="small-note">接待新顾客会替换当前服务记录；已交付作品保留在作品集中。</p>':''}<button class="salon-primary full" id="accept-client">接待顾客，聊聊需求 ${icon('arrow')}</button>`,'appointment-dialog');$('#accept-client').onclick=()=>{session=createSession(c.id);saveBlocked=false;active=c.route==='repair'?6:2;selected=null;sticker=null;past=[];future=[];session.consultation=[];sound.one('tip');refresh();persist();consultation();};});}
function refresh(){if(!session)return welcome();$('#welcome').hidden=true;$('#salon-panel').hidden=false;$('#finger-strip').hidden=false;$('#scene-controls').hidden=session.phase==='plan';scene.controls.enabled=!$('#salon-dialog').open;scene.skin.color.set(customer(session.client).skin);$('#plan-board').hidden=session.phase!=='plan';
 if(session.phase==='plan'){scene.sync(session.plan);renderPlan();}else{scene.sync(viewDesign(session));renderWork();}renderFingers();renderTools();renderCaption();$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));scene.setViewOnly(rotate||session.phase==='result');dirtyFrame=false;
}
function consultation(){
 if(!session)return;const c=customer(session.client),topics=consultationTopics(c);session.consultation??=[];
 modal(`和${c.name}聊聊`, `<div class="consultation-layout"><aside class="consultation-customer" style="--client:${c.color}">${portrait(c)}<h3>${c.name}</h3><span>${c.role}</span><p>她带来的参考图</p>${reference(c)}<small>参考风格与重点，由你重新设计。</small><button id="talk-reference" class="secondary-button full">放大查看参考图 ↗</button></aside><section class="consultation-chat"><details class="consultation-mobile-reference"><summary>查看她带来的参考图 ↗</summary>${reference(c)}<p>看风格与重点，由你重新设计。</p><button id="talk-reference-mobile" class="secondary-button full">全屏查看十指与细节 ↗</button></details><div id="chat-log" class="chat-log" role="log" aria-label="与顾客的对话"></div><div class="chat-topics" aria-label="向顾客提问">${topics.map(t=>`<button data-topic="${t.id}">${t.label}<span>＋</span></button>`).join('')}</div><div class="consultation-notes"><strong>已记下的需求 <span id="talk-count"></span></strong><ul id="talk-notes"></ul></div><button id="finish-talk" class="salon-primary full"></button></section></div>`, 'consultation-dialog');
 const log=$('#chat-log'),bubble=(name,text,mine=false)=>`<div class="chat-bubble ${mine?'mine':''}"><small>${name}</small><p>${escape(text)}</p></div>`;
 log.innerHTML=bubble(c.name,`你好，我带了这张参考图。${c.quote}`)+session.consultation.map(id=>{const t=topics.find(t=>t.id===id);return bubble('你 · 美甲师',t.question,true)+bubble(c.name,t.answer);}).join('');
 function notes(){const asked=session.consultation;$('#talk-count').textContent=`${asked.length}/4`;$('#talk-notes').innerHTML=asked.map(id=>`<li>${escape(topics.find(t=>t.id===id).note)}</li>`).join('')||'<li class="empty">点击上面的提问，先聊清楚她的心愿。</li>';$$('[data-topic]').forEach(b=>{b.disabled=asked.includes(b.dataset.topic);b.querySelector('span').textContent=b.disabled?'✓':'＋';});$('#finish-talk').disabled=asked.length!==4;$('#finish-talk').innerHTML=asked.length===4?(session.phase==='plan'?'需求已确认，开始设计':'记好了，回到工作台')+icon('arrow'):'再聊 '+(4-asked.length)+' 项需求';}
 $('#talk-reference').onclick=()=>showReference(c,consultation);$('#talk-reference-mobile').onclick=()=>showReference(c,consultation);notes();$$('[data-topic]').forEach(b=>b.onclick=()=>{const t=topics.find(t=>t.id===b.dataset.topic);if(session.consultation.includes(t.id))return;session.consultation.push(t.id);log.insertAdjacentHTML('beforeend',bubble('你 · 美甲师',t.question,true)+bubble(c.name,t.answer));notes();log.scrollTop=log.scrollHeight;sound.one('pick','ui');persist();});
 $('#finish-talk').onclick=()=>{if(session.consultation.length!==4)return;$('#salon-dialog').close();sound.one('done','ui');refresh();persist();toast(session.phase==='plan'?'已记好顾客需求。先排好十指，再开始施工。':'已记好顾客需求，回到工作台。');};log.scrollTop=log.scrollHeight;
}
function updateWallet(){try{const wallet=loadWallet();$('#wallet output').textContent=wallet.balance.toLocaleString('zh-CN');$('#wallet').setAttribute('aria-label',`查看游戏收入，余额 ${wallet.balance} 金币`);return wallet;}catch(err){$('#wallet output').textContent='—';return null;}}
$('#wallet').onclick=()=>{try{const w=loadWallet();modal('工作室的金币',`<div class="wallet-total"><span>累计收入</span><strong>${w.balance.toLocaleString('zh-CN')}<small>金币</small></strong></div><p class="modal-intro">服务费与顾客打赏都在这里。金币是游戏内奖励。</p><div class="wallet-records">${w.receipts.slice(-20).reverse().map(r=>`<div><span>${customer(r.client).name}<small>服务 ${r.service} · 打赏 ${r.tip}</small></span><strong>+${r.total}</strong></div>`).join('')||'<p>完成第一位顾客的服务，收下她的心意吧。</p>'}</div>`);}catch(err){toast(err.message,5000);}};updateWallet();
function checkout(){
 const c=customer(session.client);let reward,wallet;try{wallet=loadWallet();reward=wallet.receipts.find(r=>r.id===session.id)||serviceReward(session);}catch(err){return toast(err.message,5000);}const received=wallet.receipts.some(r=>r.id===session.id);
 modal(`${c.name}的心意`,`<div class="checkout-customer" style="--client:${c.color}">${portrait(c)}<div><small>美甲完成 · 顾客评价</small><h3>${c.name}</h3><p>“${customerReview(c)}”</p></div></div><div class="checkout-stars" aria-label="顾客五星好评">★★★★★<span>满意度 ${evaluateService(session).score} / 100</span></div><div class="checkout-tip"><span>「这一点心意，送给认真照顾我的你。」</span><strong>+${reward.tip}<small>金币打赏</small></strong>${reward.bonus?'<p>认真聊完四项需求 · 额外心意 +5</p>':''}</div><div class="checkout-total"><span>服务收入 <b>${reward.service}</b></span><span>顾客打赏 <b>${reward.tip}</b></span><strong>本次共获得 <b>${reward.total} 金币</b></strong></div><button id="claim-reward" class="salon-primary full">${received?'已入账，欣赏作品':'谢谢你，收下 '+reward.total+' 金币'} ${icon('arrow')}</button><p id="reward-status" class="small-note" role="status">${received?'这次服务已入账，刷新或再次查看不会重复领取。':'收下后金币飞入钱包，收入自动保存在当前浏览器。'}</p>`,'checkout-dialog');
 $('#claim-reward').onclick=()=>{try{const result=claimReward(session);$('#salon-dialog').close();rewardCleanup();updateWallet();if(result.added){rewardCleanup=rewardFeedback(result.receipt,result.balance,sound,$('#wallet'));toast(`服务 +${result.receipt.service} · 打赏 +${result.receipt.tip} · 共 ${result.receipt.total} 金币已入账`,3500);}else toast('这次服务已经入账。');}catch(err){$('#reward-status').textContent='未入账：'+err.message+' 请重试，原记录保留。';}};
}
function renderCaption(){const c=customer(session.client),stage=session.phase==='plan'?'十指灵感设计':STAGES[stepId(session)].name;$('#scene-title').innerHTML=`<div class="eyebrow">${session.phase==='plan'?'DESIGN BEFORE THE FIRST BRUSH':'A LITTLE CARE, AT EVERY STEP'}</div><h2>${stage}</h2><p>${c.name} · ${c.title}</p>`;$('#stage-hint').textContent=session.phase==='plan'?'点击一指编辑 · 拖动贴纸排版 · 确认后开始施工':rotate?'拖动旋转 · 双指缩放 · 点眼睛返回操作':session.phase==='result'?'拖动旋转欣赏 · 收藏或拍照留念':'在甲面按住拖动 · 右键旋转 · 下方切换手指';}
function renderFingers(){const ids=session.phase==='plan'?Array.from({length:10},(_,i)=>i):targetsFor(session),step=stepId(session);$('#finger-strip').innerHTML=[0,1].map(hand=>`<div class="finger-hand"><span>${hand?'右手':'左手'}</span>${session.plan.nails.slice(hand*5,hand*5+5).map((n,j)=>{const i=hand*5+j,done=(session.phase==='plan'?!n.unpainted:session.phase==='result')||session.work[i].done.includes(step)||!ids.includes(i);return `<button class="finger-item ${i===active?'active':''} ${done?'done':''} ${!ids.includes(i)?'preserved':''}" data-finger="${i}" aria-label="${fingerLabel(i)}${done?'，已完成':''}">${nailSVG(n,'f'+i,23,36)}<small>${['拇','食','中','无名','小'][j]}</small><i>${!ids.includes(i)?'保留':session.phase==='plan'?'':done?'✓':'·'}</i></button>`;}).join('')}</div>`).join('');$$('[data-finger]').forEach(b=>b.onclick=()=>selectFinger(Number(b.dataset.finger)));}
function selectFinger(i){if(session.lamp)return;if(session.phase==='plan'&&session.client==='zhou'&&i!==6)return toast('本次只维修右食指，其余九指保留原样。');stop();active=i;selected=null;if(session.phase!=='plan'){view='detail';scene.focus(view,i);}sound.one('pick','ui');refresh();}
