 bindReference();$('#mini-reference').onclick=()=>$('#show-reference').click();
 $$('[data-color]').forEach(b=>b.onclick=()=>mutate(()=>{n.base=b.dataset.color;n.unpainted=false;}));$('#custom-color').onchange=e=>mutate(()=>{n.base=e.target.value;n.unpainted=false;});
