 $('#plan-effect').onchange=e=>mutate(()=>{const v=e.target.value;n.pattern=['french','marble'].includes(v)?v:null;n.gradient=v==='gradient'?{color:c.palette[1],angle:0,range:.8}:null;n.finish=['french','marble','gradient'].includes(v)?'gloss':v;n.topcoat=v==='matte'?'matte':'gloss';});
 $$('[data-sticker]').forEach(b=>{b.onclick=()=>{sticker=b.dataset.sticker;selected=null;sound.one('pick');renderPlan();};b.ondragstart=e=>e.dataTransfer.setData('text/plain',b.dataset.sticker);});
