 $('#copy-opposite').onclick=()=>mutate(()=>{const j=(active+5)%10;if(session.client==='zhou')return toast('维修单保留其他九指。');session.plan.nails[j]=copyNail(n);toast('已复制到'+fingerLabel(j)+'，可撤销。');});$('#copy-colors').onclick=()=>mutate(()=>session.plan.nails.forEach((a,i)=>{if(session.client!=='zhou'||i===6){a.base=n.base;a.unpainted=n.unpainted;}}));$('#clear-plan').onclick=()=>mutate(()=>{session.plan=blankPlan(c);selected=null;sticker=null;});
