function planDimensions(canvas,n){const f=Number(canvas.dataset.plan??canvas.dataset.refIndex)%5,nw=124*(f===0?1:f===4?.66:.8),nh=170+(n.length-.45)*60;return {nw,nh,x:(160-nw)/2,y:(240-nh)/2-8};}
function drawPlanNail(canvas,n){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,{nw,nh,x,y}=planDimensions(canvas,n);ctx.clearRect(0,0,w,h);ctx.save();ctx.scale(w/160,h/240);ctx.translate(x,y);ctx.beginPath();for(let i=0;i<=50;i++){const v=i/50;ctx.lineTo((.5-halfWidth(n.shape,v))*nw,(1-v)*nh);}for(let i=50;i>=0;i--){const v=i/50;ctx.lineTo((.5+halfWidth(n.shape,v))*nw,(1-v)*nh);}ctx.closePath();ctx.shadowColor='#66472b22';ctx.shadowBlur=12;ctx.fillStyle=n.base;ctx.fill();ctx.shadowBlur=0;ctx.clip();if(!n.unpainted)ctx.drawImage(scene.texture(n),0,0,nw,nh);if(n.finish==='catEye'){ctx.save();ctx.translate(nw*.5,nh*.5);ctx.rotate(-.55);const g=ctx.createLinearGradient(-12,0,12,0);g.addColorStop(0,'#f6e1a000');g.addColorStop(.5,'#f6e1a0dd');g.addColorStop(1,'#f6e1a000');ctx.fillStyle=g;ctx.fillRect(-12,-nh,24,nh*2);ctx.restore();}for(const d of n.decorations){if(d.hidden)continue;ctx.save();ctx.translate(d.u*nw,(1-d.v)*nh);ctx.rotate(d.rotation);const tex=scene.stickers[d.type]?.image;if(tex)ctx.drawImage(tex,-nw*.115*d.scale,-nw*.115*d.scale,nw*.23*d.scale,nw*.23*d.scale);else{ctx.fillStyle=d.type==='gem'?'#d5bc82':'#fff4dc';ctx.beginPath();ctx.arc(0,0,9*d.scale,0,Math.PI*2);ctx.fill();}if(d.id===selected&&canvas.hasAttribute('data-plan')){ctx.strokeStyle='#905467';ctx.setLineDash([3,3]);ctx.strokeRect(-20,-20,40,40);}ctx.restore();}ctx.restore();}
function planPoint(e,canvas){const r=canvas.getBoundingClientRect(),d=planDimensions(canvas,session.plan.nails[Number(canvas.dataset.plan)]);return {u:((e.clientX-r.left)/r.width*160-d.x)/d.nw,v:1-((e.clientY-r.top)/r.height*240-d.y)/d.nh};}
function addSticker(i,p){if(session.client==='zhou'&&i!==6)return toast('本次只维修右食指。');const n=session.plan.nails[i];if(n.decorations.length>=18)return toast('每指最多 18 枚装饰。');remember();const d=constrainDeco(n,{id:uid(),type:sticker,u:p.u,v:p.v,scale:1,rotation:0});n.decorations.push(d);selected=d.id;sticker=null;sound.one('sticker');renderPlan();renderFingers();scheduleSave();}
function planDown(e,i,canvas){if(e.button!==0)return;if(session.client==='zhou'&&i!==6)return toast('本次只维修右食指，其余九指保留原样。');stop();const p=planPoint(e,canvas);if(active!==i){active=i;selected=null;sticker=null;renderPlan();renderFingers();return;}const n=session.plan.nails[i];if(sticker){addSticker(i,p);return;}const d=[...n.decorations].reverse().find(a=>!a.hidden&&Math.hypot(a.u-p.u,a.v-p.v)<.22);if(d){selected=d.id;if(!d.locked){remember();action={kind:'plan',id:d.id};canvas.setPointerCapture(e.pointerId);}drawPlanNail(canvas,n);}else{selected=null;renderPlan();}}
function planMove(e,i,canvas){if(action?.kind!=='plan')return;const d=session.plan.nails[i].decorations.find(a=>a.id===action.id);if(!d)return;const p=planPoint(e,canvas);constrainDeco(session.plan.nails[i],Object.assign(d,{u:p.u,v:p.v}));drawPlanNail(canvas,session.plan.nails[i]);}
