 if(session.phase==='result')return renderResult();const c=customer(session.client),id=stepId(session),stage=STAGES[id],w=session.work[active],ids=targetsFor(session),finished=ids.filter(i=>session.work[i].done.includes(id)).length;
 $('#salon-panel').innerHTML=clientHeader()+`<div class="panel-scroll"><div class="work-reference">${reference(c)}<button class="text-link" id="view-blueprint">查看十指蓝图 ↗</button></div><div class="section-label"><span>${stage.name}</span><small>${String(session.step+1).padStart(2,'0')} / ${stepsFor(c).length}</small></div><p class="stage-description">${stage.hint}</p><div class="stage-progress"><span style="width:${finished/ids.length*100}%"></span></div><div class="progress-label"><span>${finished} / ${ids.length} 指已完成</span><strong>${fingerLabel(active)}</strong></div><div class="finger-condition"><span>${c.width>1.08?'较宽':c.width<.96?'偏窄':'标准'}甲床 · ${c.curve>1.1?'较高弧度':'柔和弧度'}</span><span>${w.done.includes(id)?'✓ 本指已完成':id==='inspect'?(c.old?'带旧材料 · ':'自然本甲 · ')+(w.dirty?'需清洁':'干净'):STAGES[id].cure?'待本轮固化':'等待操作'}</span></div>${id==='fit'?`<label class="control-label">甲片宽度</label><div class="size-buttons">${[0,1,2,3,4].map(v=>`<button data-size="${v}" class="${w.fitWidth===v?'selected':''}">${['XS','S','M','L','XL'][v]}</button>`).join('')}</div><label class="control-label">甲片弧度</label><div class="row-actions">${[0,1].map(v=>`<button data-curve="${v}" class="${w.fitCurve===v?'selected':''}">${v?'高弧':'自然弧'}</button>`).join('')}</div><button id="suggest-tip" class="secondary-button full">拿取适合本指的候选甲片</button><p class="small-note">按住拿起甲片，拖到甲根后松手放下。两侧覆盖和弧度都合适才能继续。</p>`:''}${id==='magnet'?`<label class="control-label">光带方向<input id="magnet-angle" type="range" min="-1.5" max="1.5" step=".05" value="${w.magnet.angle}"></label><button id="confirm-magnet" class="secondary-button full">锁定本指布局，待照灯</button>`:''}${STAGES[id].cure?`<div class="lamp-panel"><div class="lamp-symbol">◠</div><strong>纱光 · LED 固化灯</strong><p>本轮：${id==='cureBase'?'基础层':id==='cureColor'?'款式层':'封层'} · 整手五指一起</p><div class="row-actions"><button data-lamp="0">左手整手入灯</button><button data-lamp="1">右手整手入灯</button></div><small>短动画模拟 · 一次固化本手当前层，不是逐指入灯</small></div>`:id==='finish'?`<button id="deliver" class="salon-primary full">检查并交付作品 ${icon('arrow')}</button>`:`<div class="tool-instruction">${icon('paint')}<span>${id==='file'?'在指尖前缘锉动':id==='inspect'?'点击甲面记录甲况':id==='fit'?'拖到甲根，松手放下':id==='decor'?'点击甲面上的虚线图案落位':id==='magnet'?'在甲面移动磁铁':'在甲面来回移动工具'}</span></div>${id==='build'?'<button id="check-side" class="secondary-button full">查看侧面 · 建构厚薄</button>':''}<div class="assistance"><button id="assist-hand" ${finished===0?'disabled':''}>辅助处理本手其余指</button><small>先亲手完成一指，再减少重复操作。</small></div>`}<div class="step-trail">${stepsFor(c).map((k,i)=>`<span class="${i===session.step?'current':i<session.step?'completed':''}">${i<session.step?'✓ ':''}${STAGES[k].short}</span>`).join('')}</div></div><div class="panel-footer"><span id="save-label">已保存 · 当前浏览器</span><button class="salon-primary full" id="next-stage" ${finished!==ids.length||id==='finish'?'disabled':''}>${finished===ids.length?'本阶段完成，继续':'完成本阶段后继续'} ${icon('arrow')}</button></div>`;
 bindReference();$('#view-blueprint').onclick=()=>modal('已确认的十指蓝图',`<div class="blueprint-preview">${session.plan.nails.map((n,i)=>`<div>${nailSVG(n,'b'+i,52,90)}<small>${fingerLabel(i)}</small></div>`).join('')}</div><p class="modal-intro">${c.limit}</p>`);
