 $$('[data-size]').forEach(b=>b.onclick=()=>mutate(()=>w.fitWidth=Number(b.dataset.size)));$$('[data-curve]').forEach(b=>b.onclick=()=>mutate(()=>w.fitCurve=Number(b.dataset.curve)));
 if($('#suggest-tip'))$('#suggest-tip').onclick=()=>mutate(()=>{w.fitWidth=(active%5===0?3:active%5===4?0:1)+(c.width>1.1?1:0);w.fitCurve=c.curve>1.1?1:0;sound.one('tip');toast('候选甲片已就绪，按住拿起并拖到甲根放下。');});
