function assistHand(){const id=stepId(session),ids=targetsFor(session).filter(i=>Math.floor(i/5)===Math.floor(active/5));if(!targetsFor(session).some(i=>session.work[i].done.includes(id)))return;remember();for(const i of ids){const w=session.work[i];if(id==='build')w.build=.7;if(id==='decor')w.coverage.decor=session.plan.nails[i].decorations.map((_,k)=>k);if(id==='magnet')w.magnet=clone(session.work[active].magnet);complete(session,i);}sound.one('done','ui');refresh();scheduleSave();toast('本手其余指已辅助完成；另一只手仍由你选择处理。');}
function startLamp(hand){stop();try{beginLamp(session,hand);}catch(e){toast(e.message);return;}view='both';scene.focus(view,active);objects.lamp(hand,true);sound.one('lamp');renderLamp();persist();}
function renderLamp(){const l=session.lamp;if(!l){$('#lamp-overlay').hidden=true;return;}$('#lamp-overlay').hidden=false;$('#lamp-overlay').innerHTML=`<div><span class="eyebrow">HAND SENSOR / LED</span><h3>${l.hand?'右手':'左手'}整手入灯</h3><strong id="lamp-count">正在入灯</strong><p>五指一起 · ${STAGES[stepId(session)].name}</p><div class="row-actions"><button id="interrupt-lamp">提前取手</button><button id="speed-lamp">缩短等待</button></div></div>`;$('#interrupt-lamp').onclick=()=>{session.lamp=null;sound.lamp(false);objects.restore();renderLamp();persist();toast('提前取手，本手本轮尚未固化，可整手重新入灯。');};$('#speed-lamp').onclick=()=>{if(session.lamp)session.lamp.remaining=Math.min(session.lamp.remaining,.4);};}
function currentReward(){try{return loadWallet().receipts.find(r=>r.id===session.id)||serviceReward(session);}catch{return serviceReward(session);}}
function renderResult(){const c=customer(session.client),evaluation=evaluateService(session);$('#salon-panel').innerHTML=clientHeader()+`<div class="panel-scroll result-panel"><div class="eyebrow">MADE WITH CARE, WORN WITH JOY</div><h2>这份心意，<br>刚刚好。</h2><div class="result-score">${evaluation.score}<small>/ 100</small></div><blockquote>“${c.id==='zhou'?'小星星回来了，其他指甲也都保留着。谢谢你这么细心。':'就是我想要的感觉。你把参考里的美，做成了适合我的样子。'}”</blockquote><div class="result-checks"><span>✓ 顾客要求</span><span>✓ 服务步骤</span><span>✓ 三轮固化</span><span>✓ 十指搭配</span></div><div class="result-price"><span>服务收入</span><strong>${c.price} 金币</strong></div><div class="tip-card"><span>顾客的心意</span><strong>+${currentReward().tip}<small>金币打赏</small></strong><button id="open-checkout" class="salon-primary full">交付对话与收入 ${icon('arrow')}</button></div><button class="salon-primary full" id="save-result">${icon('shelf')} 收藏完整作品</button><button class="secondary-button full" id="photo-result">${icon('camera')} 拍照下载</button><button class="text-link full" id="backup-result">导出可编辑作品</button><p class="small-note">作品保存在当前浏览器，建议导出备份。自由创作可打开收藏继续绘画。</p></div><div class="panel-footer"><button class="salon-primary full" id="next-client">接待下一位顾客 ${icon('arrow')}</button></div>`;bindReference();$('#open-checkout').onclick=checkout;$('#save-result').onclick=saveResult;$('#photo-result').onclick=()=>{objects.restore();scene.focus('both');download(scene.photo(),c.title+'.png');sound.one('camera');};$('#backup-result').onclick=()=>exportJSON(session.plan,c.title+'.json');$('#next-client').onclick=book;}
function saveResult(){try{const works=JSON.parse(localStorage.getItem(ALBUM_KEY)||'[]');if(!Array.isArray(works))throw Error();const previous=works.find(w=>w.id===session.id),entry={id:session.id,client:session.client,name:session.plan.name,design:clone(session.plan),score:evaluateService(session).score,date:Date.now()};if(previous)Object.assign(previous,entry);else works.unshift(entry);saveWork(session.plan);localStorage.setItem(ALBUM_KEY,JSON.stringify(works));sound.one('done','ui');toast('已收藏完整作品，自由创作中也可继续编辑。');}catch{toast('收藏失败，旧作品保留；请先导出备份。',5000);}}
function album(){let works=[];try{works=JSON.parse(localStorage.getItem(ALBUM_KEY)||'[]');if(!Array.isArray(works)||works.length>300)throw Error();works=works.map(w=>({...w,design:validateDesign(w.design)}));}catch{return toast('作品集读取失败，请保留原始数据并导出备份。');}modal('把每一次心意，收藏起来',works.length?`<div class="album-grid">${works.map((w,j)=>`<button data-album="${j}" class="album-card"><div class="album-nails">${w.design.nails.slice(0,5).map((n,i)=>nailSVG(n,'a'+j+i,36,72)).join('')}</div><h3>${escape(w.name)}</h3><small>${customer(w.client)?.name||'自由作品'} · ${w.score} 分 · 完整十指</small></button>`).join('')}</div>`:'<p class="modal-intro">完成第一位顾客的服务后，在交付页收藏她的十指作品。</p>');$$('[data-album]').forEach(b=>b.onclick=()=>{const work=works[Number(b.dataset.album)];modal(escape(work.name),`<div class="blueprint-preview">${work.design.nails.map((n,i)=>`<div>${nailSVG(n,'g'+i,48,85)}<small>${fingerLabel(i)}</small></div>`).join('')}</div><button id="export-album" class="salon-primary full">导出完整可编辑作品</button><a class="secondary-button full" href="?mode=free">进入自由创作继续编辑</a>`);$('#export-album').onclick=()=>exportJSON(work.design,work.name+'.json');});}
function updateMusicUi(){
 const ready=!!sound.ctx,playing=ready&&sound.musicPlaying&&!sound.musicError,percent=Math.round(sound.channels.music*100)+'%',label=sound.musicError?'重试播放伴奏':playing?'暂停伴奏':'播放伴奏';
 $('#dock-track').value=String(sound.track);$('#dock-status').title=sound.musicStatus;$('#dock-status').textContent=!ready&&!sound.muted&&sound.musicPlaying?'点击播放':sound.musicStatus;
 $('#dock-toggle').innerHTML=icon(playing?'pause':'play')+'<small>'+(sound.musicError?'重试':playing?'暂停':'播放')+'</small>';$('#dock-toggle').setAttribute('aria-label',label);$('#dock-toggle').title=label;$('.music-dock').classList.toggle('is-playing',playing&&!sound.muted&&!sound.musicSuspended&&sound.channels.music>0);
 $('#dock-volume').value=String(sound.channels.music);$('#dock-volume-value').textContent=percent;$('#dock-volume').setAttribute('aria-valuetext',percent);
 if(!$('#music-track'))return;$('#music-track').value=String(sound.track);$('#music-status').textContent=sound.musicStatus;$('#music-toggle').textContent=sound.musicError?'重试播放':sound.musicPlaying?'暂停':'播放';$('#music-toggle').setAttribute('aria-label',label);$('#music-volume-value').textContent=percent;$('[data-volume="music"]').value=String(sound.channels.music);
}
async function toggleMusic(){if(!sound.ctx){sound.musicPlaying=true;await unlock();sound.savePrefs();}else if(sound.musicError){sound.musicPlaying=true;await sound.ctx.resume();sound.musicElement?.load();await sound.playMusic();sound.savePrefs();}else await sound.toggleMusic();updateMusicUi();}
function selectMusicTrack(index){sound.selectTrack(index);if(!sound.ctx)unlock();}
sound.onMusicChange=updateMusicUi;
$('#dock-track').onchange=e=>selectMusicTrack(Number(e.target.value));$('#dock-prev').onclick=()=>selectMusicTrack((sound.track+MUSIC_TRACKS.length-1)%MUSIC_TRACKS.length);$('#dock-next').onclick=()=>selectMusicTrack((sound.track+1)%MUSIC_TRACKS.length);$('#dock-toggle').onclick=toggleMusic;$('#dock-volume').oninput=e=>sound.set('music',Number(e.target.value));updateMusicUi();
function settings(){modal('音乐与声音',`<p class="modal-intro">挑一首喜欢的伴奏，把工作台的声音调到舒服的大小。</p><section class="music-card" aria-label="伴奏播放器"><div class="music-card-heading"><span>工作室的音乐</span><small id="music-status" role="status"></small></div><label class="control-label" for="music-track">选择伴奏</label><select id="music-track">${MUSIC_TRACKS.map((t,i)=>`<option value="${i}">${t.title}</option>`).join('')}</select><div class="row-actions music-actions"><button id="music-prev" aria-label="上一首伴奏">上一首</button><button id="music-toggle">暂停</button><button id="music-next" aria-label="下一首伴奏">下一首</button></div><label class="control-label">伴奏音量 <output id="music-volume-value"></output><input type="range" data-volume="music" aria-label="伴奏音量" min="0" max="1" step=".01" value="${sound.channels.music}"></label><p>播完自动接下一首 · 曲目与音量会记住</p></section><label class="setting-toggle"><span>总静音</span><input type="checkbox" id="mute" ${sound.muted?'checked':''}></label>${Object.entries({tools:'工具与材质',ui:'完成与界面提示',room:'工作室环境'}).map(([k,t])=>`<label class="control-label">${t}<input type="range" data-volume="${k}" min="0" max="1" step=".05" value="${sound.channels[k]}"></label>`).join('')}<div class="settings-backup"><button id="export-session" class="secondary-button full">导出当前服务备份</button><button id="import-session" class="secondary-button full">导入服务备份</button><p class="small-note">旧版自由创作作品保留原存储。不同网站的浏览器存档不互通，请使用备份迁移。</p></div>`);$('#music-track').onchange=e=>sound.selectTrack(Number(e.target.value));$('#music-prev').onclick=()=>sound.selectTrack((sound.track+MUSIC_TRACKS.length-1)%MUSIC_TRACKS.length);$('#music-next').onclick=()=>sound.selectTrack((sound.track+1)%MUSIC_TRACKS.length);$('#music-toggle').onclick=toggleMusic;updateMusicUi();$('#mute').onchange=e=>sound.set('muted',e.target.checked);$$('[data-volume]').forEach(input=>input.oninput=()=>sound.set(input.dataset.volume,Number(input.value)));$('#export-session').onclick=()=>session?exportJSON(session,'指间诗-服务备份.json'):toast('还没有正在进行的服务。');$('#import-session').onclick=()=>$('#backup-input').click();}
function download(url,name){const a=document.createElement('a');a.href=url;a.download=name;a.click();}
function exportJSON(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));download(url,name);setTimeout(()=>URL.revokeObjectURL(url),2000);}
$('#backup-input').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>8000000)throw Error('备份超过 8 MB');const next=validateSession(JSON.parse(await file.text()));session=next;saveBlocked=false;past=[];future=[];session.lamp=null;objects.restore();$('#salon-dialog').close();refresh();persist();toast('服务备份已恢复。');}catch(err){toast('导入失败：'+err.message,5000);}finally{e.target.value='';}};
$('#settings').onclick=async()=>{unlock();settings();};$('#album').onclick=album;$('#home').onclick=book;$('#help').onclick=()=>modal('慢慢做，每一步都有回应',`<div class="help-copy"><p><b>先看参考，排好十指。</b> 设计板中先点一指，再选配色或贴纸。贴纸可拖动，右侧可旋转、缩放、锁定与排序。</p><p><b>点击手指，靠近操作。</b> 下方选择指位。检查用点击；试片按住拿起、拖到甲根松手；清洁、刷涂、建构用按住拖动；修形在指尖前缘锉动。</p><p><b>看见变化，听见接触。</b> 工具接触甲面才产生操作声；停手或离开甲面就停止。先完成一指，再使用本手辅助。</p><p><b>照灯锁定材料。</b> 每轮分别处理左右手。提前取手不会完成固化，可缩短等待。猫眼光带在款式层固化后锁定。</p><p><b>换角度检查。</b> 右键旋转，滚轮缩放；触屏先点眼睛切到旋转，再点回操作。侧面查看建构厚薄。</p><p><b>保留作品。</b> 服务自动保存；交付后收藏、拍照或导出。Ctrl+Z 撤销本阶段；切换阶段后不撤回已固化内容。</p></div>`);
$('#undo').onclick=()=>restore();$('#redo').onclick=()=>restore(true);$('#side-view').onclick=()=>{if(session&&!session.lamp)objects.side(active);};$('#rotate').onclick=()=>{rotate=!rotate;scene.setViewOnly(rotate);$('#rotate').classList.toggle('active',rotate);renderCaption();};$$('[data-view]').forEach(b=>b.onclick=()=>{if(session?.lamp)return;stop();view=b.dataset.view;scene.focus(view,active);$$('[data-view]').forEach(x=>x.classList.toggle('active',x===b));});

const canvas=scene.renderer.domElement;
canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('pointerdown',e=>{if(e.button!==0||!session||session.phase!=='work'||session.lamp||rotate||$('#salon-dialog').open)return;const hit=scene.pick(e.clientX,e.clientY);if(!hit)return;const id=stepId(session);if(!targetsFor(session).includes(hit.index)){toast('这指保留原样，本次只处理订单指定的手指。');return;}if(hit.index!==active){active=hit.index;view='detail';scene.focus(view,active);refresh();return;}remember();action={index:active,last:hit,kind:id,time:e.timeStamp,newStroke:true,travel:0};canvas.setPointerCapture(e.pointerId);if(id==='fit'){sound.one('tip');objects.tool(hit,'tip');}else applyHit(hit,e,0);});
canvas.addEventListener('pointermove',e=>{if(!session||session.phase!=='work'||rotate)return;const hit=scene.pick(e.clientX,e.clientY);if(action&&hit?.index===active){const distance=action.newStroke?0:Math.hypot(hit.u-action.last.u,hit.v-action.last.v);action.travel+=Math.hypot(hit.u-action.last.u,hit.v-action.last.v);if(action.kind==='fit')objects.tool(hit,'tip');else applyHit(hit,e,distance);action.last=hit;action.time=e.timeStamp;action.newStroke=false;}else if(action){action.newStroke=true;sound.stopContact();objects.tool(null);$('#contact-feedback').className='contact-feedback';}});
function applyHit(hit,e,distance,placing=false){const id=stepId(session),stage=STAGES[id],before=session.work[active].done.includes(id);if(before)return;let changed=false;const starting=!!action?.newStroke,speed=distance/Math.max(.008,(e.timeStamp-(action?.time||e.timeStamp))/1000),pressure=e.pointerType==='pen'?Math.max(.15,e.pressure):.55;
 if(id==='decor')changed=placeDecoration(session,active,hit.u,hit.v);else changed=workAt(session,active,hit.u,hit.v,distance,{start:starting,placing});
 objects.tool(hit,stage.tool,speed,pressure);if(action)action.newStroke=false;if(!changed){sound.stopContact();if(id==='fit'&&placing){sound.one('error','ui');toast('对齐甲根再放下，检查甲片两侧宽度和弧度。');}return;}
 const feedback=$('#contact-feedback');feedback.style.left=e.clientX+'px';feedback.style.top=e.clientY+'px';feedback.className='contact-feedback touching '+stage.tool;
 if(['inspect','fit','decor'].includes(id))sound.one(id==='decor'?(session.plan.nails[active].decorations.some(d=>['gem','pearl'].includes(d.type))?'jewel':'sticker'):id==='fit'?'cap':'pick');else if(stage.sound)sound.contact(stage.sound,Math.min(8,speed),pressure,hit.u-.5);if(['file','remove','dust'].includes(id))objects.dust();
 const condition=$('.finger-condition span:last-child');if(condition)condition.textContent=`${Math.round(progress(session,active)*100)}% · ${id==='bond'?'从甲根向前排泡':id==='file'?'自由缘修整':'沿轨迹铺开'}`;
 if(session.work[active].done.includes(id)&&!before){sound.stopContact();sound.one('done','ui');toast(fingerLabel(active)+' · '+stage.name+'完成');dirtyFrame=true;setTimeout(()=>{if(session?.phase==='work'&&stepId(session)===id){renderWork();renderFingers();}},40);}dirtyFrame=true;scheduleSave();}
canvas.addEventListener('pointerup',e=>{if(action?.kind==='fit'){const hit=scene.pick(e.clientX,e.clientY);if(hit?.index===active)applyHit(hit,e,action.travel,true);}stop();if(session?.phase==='work'){renderWork();renderFingers();}});
for(const name of ['pointercancel','lostpointercapture'])canvas.addEventListener(name,()=>{stop();if(session?.phase==='work'){renderWork();renderFingers();}});
window.addEventListener('pointerup',()=>{if(action?.kind!=='plan')stop();});
window.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||$('#salon-dialog').open)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();restore(e.shiftKey);}if(e.key==='Escape')stop();});
 window.addEventListener('blur',()=>{stop();paused=true;persist();sound.pause();});window.addEventListener('focus',()=>{paused=false;sound.resume();lastFrame=performance.now();});document.addEventListener('visibilitychange',()=>{paused=document.hidden;stop();persist();if(paused)sound.pause();else{sound.resume();lastFrame=performance.now();}});window.addEventListener('pagehide',persist);
function frame(t){const dt=Math.min(.08,(t-lastFrame)/1000);lastFrame=t;sound.tick();if(dirtyFrame&&session){scene.sync(session.phase==='plan'?session.plan:viewDesign(session));dirtyFrame=false;}if(session?.lamp&&!paused&&!$('#salon-dialog').open){const phase=session.lamp.phase;if(advanceLamp(session,dt)){sound.lamp(false);renderLamp();past=[];future=[];refresh();persist();toast('本手固化完成，材料已锁定。');}else{objects.lampState(session.lamp);sound.lamp(session.lamp.phase==='cure');if(phase!==session.lamp.phase)persist();if($('#lamp-count'))$('#lamp-count').innerHTML=session.lamp.phase==='enter'?'正在入灯':session.lamp.phase==='exit'?'正在取手':session.lamp.remaining.toFixed(1)+'<small>s</small>';}}if(!paused&&!$('#salon-dialog').open)objects.tick(dt);requestAnimationFrame(frame);}
requestAnimationFrame(frame);
if(session?.lamp)session.lamp=null;
welcome();
window.render_game_to_text=()=>JSON.stringify({mode:session?.phase||'welcome',customer:session?.client,step:session?stepId(session):null,active,targets:session?targetsFor(session):[],progress:session?session.work.map((w,i)=>({finger:fingerLabel(i),done:w.done,coverage:progress(session,i)})):[],lamp:session?.lamp,paused,audio:{running:sound.ctx?.state,contact:sound.contactKind,failed:!!sound.failed}});
window.advanceTime=ms=>{for(let t=0;t<ms;t+=20){if(session?.lamp){const done=advanceLamp(session,Math.min(20,ms-t)/1000);if(done){sound.lamp(false);renderLamp();refresh();persist();}else{objects.lampState(session.lamp);sound.lamp(session.lamp.phase==='cure');}}objects.tick(.02);}};
window.nailSalon={get session(){return clone(session);},get scene(){return scene;},get sound(){return sound;},get interaction(){return objects.interaction;},project:(i,u,v)=>scene.project(i,u,v),get active(){return active;}};
